    assert_eq!(
        modified_utf8::encode("emoji \u{1f600}"),
        [
            0x65, 0x6d, 0x6f, 0x6a, 0x69, 0x20, 0xed, 0xa0, 0xbd, 0xed, 0xb8, 0x80
        ]
    );
